1	/*
2	 * VelaWear Agent - Main Entry Point
3	 *
4	 * This is the main entry point for the VelaWear Agent application.
5	 * It initializes all subsystems and starts the main event loop.
6	 *
7	 * Author: pjjuihj
8	 * Team: 329 - dela
9	 */
10	
11	#include <nuttx/config.h>
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <unistd.h>
16	#include <errno.h>
17	#include <syslog.h>
18	
19	#include "velawear.h"
20	
21	/* Global agent instance */
22	
23	static velawear_agent_t g_agent;
24	
25	/* Forward declarations */
26	
27	static int velawear_init(velawear_agent_t *agent);
28	static int velawear_start(velawear_agent_t *agent);
29	static void velawear_cleanup(velawear_agent_t *agent);
30	static void velawear_signal_handler(int signo);
31	
32	/****************************************************************************
33	 * Public Functions
34	 ****************************************************************************/
35	
36	int main(int argc, char *argv[])
37	{
38	  int ret;
39	
40	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
41	
42	  /* Initialize agent structure */
43	
44	  memset(&g_agent, 0, sizeof(velawear_agent_t));
45	  g_agent.running = false;
46	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
47	
48	  /* Initialize subsystems */
49	
50	  ret = velawear_init(&g_agent);
51	  if (ret < 0)
52	    {
53	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
54	      return EXIT_FAILURE;
55	    }
56	
57	  /* Start the agent */
58	
59	  ret = velawear_start(&g_agent);
60	  if (ret < 0)
61	    {
62	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
63	      velawear_cleanup(&g_agent);
64	      return EXIT_FAILURE;
65	    }
66	
67	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
68	
69	  /* Main loop - wait for termination signal */
70	
71	  while (g_agent.running)
72	    {
73	      sleep(1);
74	    }
75	
76	  /* Cleanup */
77	
78	  velawear_cleanup(&g_agent);
79	  syslog(LOG_INFO, "[VelaWear] Agent stopped\n");
80	
81	  return EXIT_SUCCESS;
82	}
83	
84	/****************************************************************************
85	 * Private Functions
86	 ****************************************************************************/
87	
88	static int velawear_init(velawear_agent_t *agent)
89	{
90	  int ret;
91	
92	  /* Initialize configuration */
93	
94	  ret = velawear_config_init(&agent->config);
95	  if (ret < 0)
96	    {
97	      syslog(LOG_ERR, "[VelaWear] Config init failed: %d\n", ret);
98	      return ret;
99	    }
100	
101	  /* Initialize state manager */
102	
103	  ret = state_manager_init(&agent->state);
104	  if (ret < 0)
105	    {
106	      syslog(LOG_ERR, "[VelaWear] State manager init failed: %d\n", ret);
107	      return ret;
108	    }
109	
110	  /* Initialize event manager */
111	
112	  ret = event_manager_init(&agent->events);
113	  if (ret < 0)
114	    {
115	      syslog(LOG_ERR, "[VelaWear] Event manager init failed: %d\n", ret);
116	      return ret;
117	    }
118	
119	  /* Initialize decision engine */
120	
121	  ret = decision_engine_init(&agent->engine, &agent->config);
122	  if (ret < 0)
123	    {
124	      syslog(LOG_ERR, "[VelaWear] Decision engine init failed: %d\n", ret);
125	      return ret;
126	    }
127	
128	  /* Initialize action manager */
129	
130	  ret = action_manager_init(&agent->actions);
131	  if (ret < 0)
132	    {
133	      syslog(LOG_ERR, "[VelaWear] Action manager init failed: %d\n", ret);
134	      return ret;
135	    }
136	
137	  /* Initialize sensor drivers */
138	
139	  ret = imu_sensor_init(&agent->imu);
140	  if (ret < 0)
141	    {
142	      syslog(LOG_WARNING, "[VelaWear] IMU sensor init failed: %d\n", ret);
143	      /* Non-fatal: continue without IMU */
144	    }
145	
146	  ret = audio_sensor_init(&agent->audio);
147	  if (ret < 0)
148	    {
149	      syslog(LOG_WARNING, "[VelaWear] Audio sensor init failed: %d\n", ret);
150	      /* Non-fatal: continue without audio */
151	    }
152	
153	  /* Initialize LLM client */
154	
155	  ret = velawear_llm_init(&agent->llm);
156	  if (ret < 0)
157	    {
158	      syslog(LOG_WARNING, "[VelaWear] LLM init failed: %d\n", ret);
159	      /* Non-fatal: continue without LLM */
160	    }
161	
162	  return OK;
163	}
164	
165	static int velawear_start(velawear_agent_t *agent)
166	{
167	  int ret;
168	
169	  /* Start event manager thread */
170	
171	  ret = event_manager_start(&agent->events);
172	  if (ret < 0)
173	    {
174	      syslog(LOG_ERR, "[VelaWear] Event manager start failed: %d\n", ret);
175	      return ret;
176	    }
177	
178	  /* Start decision engine thread */
179	
180	  ret = decision_engine_start(&agent->engine);
181	  if (ret < 0)
182	    {
183	      syslog(LOG_ERR, "[VelaWear] Decision engine start failed: %d\n", ret);
184	      return ret;
185	    }
186	
187	  /* Mark agent as running */
188	
189	  agent->running = true;
190	
191	  return OK;
192	}
193	
194	static void velawear_cleanup(velawear_agent_t *agent)
195	{
196	  /* Stop subsystems in reverse order */
197	
198	  agent->running = false;
199	
200	  velawear_llm_cleanup(&agent->llm);
201	  action_manager_cleanup(&agent->actions);
202	  decision_engine_cleanup(&agent->engine);
203	  event_manager_cleanup(&agent->events);
204	  state_manager_cleanup(&agent->state);
205	  velawear_config_cleanup(&agent->config);
206	}
207	
208	static void velawear_signal_handler(int signo)
209	{
210	  syslog(LOG_INFO, "[VelaWear] Received signal %d, shutting down\n", signo);
211	  g_agent.running = false;
212	}
