1	/*
2	 * VelaWear Agent - Event Manager Implementation
3	 *
4	 * Manages all events from sensors, BLE, touch, and system.
5	 *
6	 * Author: pjjuihj
7	 * Team: 329 - dela
8	 */
9	
10	#include <nuttx/config.h>
11	#include <stdio.h>
12	#include <stdlib.h>
13	#include <string.h>
14	#include <errno.h>
15	#include <syslog.h>
16	#include <pthread.h>
17	#include <mqueue.h>
18	#include <fcntl.h>
19	#include <unistd.h>
20	
21	#include "velawear.h"
22	#include "event_manager.h"
23	
24	/****************************************************************************
25	 * Private Functions
26	 ****************************************************************************/
27	
28	static void *event_manager_thread(void *arg)
29	{
30	  velawear_events_t *events = (velawear_events_t *)arg;
31	  velawear_event_t event;
32	  int ret;
33	
34	  syslog(LOG_INFO, "[EventMgr] Thread started\n");
35	
36	  while (events->running)
37	    {
38	      /* Pop event from queue with timeout */
39	
40	      ret = event_manager_pop(events, &event, 1000);
41	      if (ret < 0)
42	        {
43	          /* Timeout or error, continue */
44	
45	          continue;
46	        }
47	
48	      /* Dispatch event to registered handlers */
49	
50	      pthread_mutex_lock(&events->lock);
51	
52	      for (int i = 0; i < events->handler_count; i++)
53	        {
54	          if (events->handlers[i].event_type == event.type ||
55	              events->handlers[i].event_type == VELAWEAR_EVENT_NONE)
56	            {
57	              ret = events->handlers[i].handler(&event,
58	                                                events->handlers[i].context);
59	              if (ret < 0)
60	                {
61	                  syslog(LOG_WARNING,
62	                         "[EventMgr] Handler %d returned error: %d\n",
63	                         i, ret);
64	                }
65	            }
66	        }
67	
68	      pthread_mutex_unlock(&events->lock);
69	    }
70	
71	  syslog(LOG_INFO, "[EventMgr] Thread stopped\n");
72	  return NULL;
73	}
74	
75	/****************************************************************************
76	 * Public Functions
77	 ****************************************************************************/
78	
79	int event_manager_init(velawear_events_t *events)
80	{
81	  struct mq_attr attr;
82	
83	  memset(events, 0, sizeof(velawear_events_t));
84	
85	  /* Initialize mutex */
86	
87	  pthread_mutex_init(&events->lock, NULL);
88	
89	  /* Create message queue */
90	
91	  attr.mq_flags = 0;
92	  attr.mq_maxmsg = EVENT_QUEUE_SIZE;
93	  attr.mq_msgsize = sizeof(velawear_event_t);
94	  attr.mq_curmsgs = 0;
95	
96	  events->queue = mq_open("/velawear_events", O_CREAT | O_RDWR, 0644,
97	                          &attr);
98	  if (events->queue == (mqd_t)-1)
99	    {
100	      syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
101	             errno);
102	      return VELAWEAR_ERR_IO;
103	    }
104	
105	  events->running = false;
106	  events->handler_count = 0;
107	
108	  syslog(LOG_INFO, "[EventMgr] Initialized\n");
109	  return VELAWEAR_OK;
110	}
111	
112	int event_manager_start(velawear_events_t *events)
113	{
114	  int ret;
115	
116	  if (events->running)
117	    {
118	      return VELAWEAR_ERR_BUSY;
119	    }
120	
121	  events->running = true;
122	
123	  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
124	  if (ret != 0)
125	    {
126	      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
127	      events->running = false;
128	      return VELAWEAR_ERR_IO;
129	    }
130	
131	  syslog(LOG_INFO, "[EventMgr] Started\n");
132	  return VELAWEAR_OK;
133	}
134	
135	void event_manager_cleanup(velawear_events_t *events)
136	{
137	  if (events->running)
138	    {
139	      events->running = false;
140	      pthread_join(events->thread, NULL);
141	    }
142	
143	  if (events->queue != (mqd_t)-1)
144	    {
145	      mq_close(events->queue);
146	      mq_unlink("/velawear_events");
147	    }
148	
149	  pthread_mutex_destroy(&events->lock);
150	
151	  syslog(LOG_INFO, "[EventMgr] Cleaned up\n");
152	}
153	
154	int event_manager_push(velawear_events_t *events, velawear_event_t *event)
155	{
156	  int ret;
157	
158	  if (events->queue == (mqd_t)-1)
159	    {
160	      return VELAWEAR_ERR_IO;
161	    }
162	
163	  ret = mq_send(events->queue, (const char *)event,
164	                sizeof(velawear_event_t), event->priority);
165	  if (ret < 0)
166	    {
167	      syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", errno);
168	      return VELAWEAR_ERR_IO;
169	    }
170	
171	  return VELAWEAR_OK;
172	}
173	
174	int event_manager_pop(velawear_events_t *events, velawear_event_t *event,
175	                      int timeout_ms)
176	{
177	  struct timespec timeout;
178	  ssize_t nbytes;
179	
180	  if (events->queue == (mqd_t)-1)
181	    {
182	      return VELAWEAR_ERR_IO;
183	    }
184	
185	  /* Calculate timeout */
186	
187	  clock_gettime(CLOCK_REALTIME, &timeout);
188	  timeout.tv_sec += timeout_ms / 1000;
189	  timeout.tv_nsec += (timeout_ms % 1000) * 1000000;
190	  if (timeout.tv_nsec >= 1000000000)
191	    {
192	      timeout.tv_sec++;
193	      timeout.tv_nsec -= 1000000000;
194	    }
195	
196	  nbytes = mq_timedreceive(events->queue, (char *)event,
197	                           sizeof(velawear_event_t), NULL, &timeout);
198	  if (nbytes < 0)
199	    {
200	      if (errno == ETIMEDOUT)
201	        {
202	          return VELAWEAR_ERR_TIMEOUT;
203	        }
204	
205	      return VELAWEAR_ERR_IO;
206	    }
207	
208	  return VELAWEAR_OK;
209	}
210	
211	int event_manager_register_handler(velawear_events_t *events,
212	                                   uint32_t event_type,
213	                                   event_handler_t handler,
214	                                   void *context,
215	                                   int priority)
216	{
217	  pthread_mutex_lock(&events->lock);
218	
219	  if (events->handler_count >= EVENT_HANDLER_MAX)
220	    {
221	      pthread_mutex_unlock(&events->lock);
222	      return VELAWEAR_ERR_NOMEM;
223	    }
224	
225	  events->handlers[events->handler_count].event_type = event_type;
226	  events->handlers[events->handler_count].handler = handler;
227	  events->handlers[events->handler_count].context = context;
228	  events->handlers[events->handler_count].priority = priority;
229	  events->handler_count++;
230	
231	  pthread_mutex_unlock(&events->lock);
232	
233	  syslog(LOG_INFO, "[EventMgr] Registered handler for type %d\n", event_type);
234	  return VELAWEAR_OK;
235	}
