20	
21	/****************************************************************************
22	 * Private Functions
23	 ****************************************************************************/
24	
25	static void notify_callbacks(velawear_state_mgr_t *mgr)
26	{
27	  for (int i = 0; i < mgr->callback_count; i++)
28	    {
29	      if (mgr->callbacks[i])
30	        {
31	          mgr->callbacks[i](&mgr->state, mgr->contexts[i]);
32	        }
33	    }
34	}
35	
36	/****************************************************************************
37	 * Public Functions
38	 ****************************************************************************/
39	
40	int state_manager_init(velawear_state_mgr_t *mgr)
41	{
