22	/****************************************************************************
23	 * Hardcoded Rules (Layer 0 - Emergency)
24	 ****************************************************************************/
25	
26	static bool fall_detected_condition(velawear_state_t *state,
27	                                    velawear_event_t *event)
28	{
29	  return event && event->type == VELAWEAR_EVENT_FALL;
30	}
31	
32	static int fall_detected_action(velawear_state_t *state, void *context)
33	{
34	  syslog(LOG_WARNING, "[Decision] FALL DETECTED! Sending emergency alert\n");
35	
36	  /* TODO: Send emergency BLE notification */
37	  /* TODO: Show emergency UI */
38	  /* TODO: Vibrate motor */
39	
40	  state->fall_count_today++;
41	  return VELAWEAR_OK;
42	}
43	
44	static bool heart_rate_critical_condition(velawear_state_t *state,
45	                                          velawear_event_t *event)
46	{
47	  return state->heart_rate > 180.0f || state->heart_rate < 40.0f;
48	}
49	
50	static int heart_rate_critical_action(velawear_state_t *state, void *context)
51	{
52	  syslog(LOG_WARNING, "[Decision] Heart rate critical: %.1f\n",
53	         state->heart_rate);
54	
55	  /* TODO: Show warning UI */
56	  /* TODO: Send BLE alert */
57	
58	  return VELAWEAR_OK;
59	}
60	
61	static bool battery_critical_condition(velawear_state_t *state,
62	                                       velawear_event_t *event)
63	{
64	  return state->battery_level < 5 && !state->is_charging;
65	}
66	
67	static int battery_critical_action(velawear_state_t *state, void *context)
68	{
