77	
78	/****************************************************************************
79	 * Private Functions
80	 ****************************************************************************/
81	
82	static void *decision_engine_thread(void *arg)
83	{
84	  velawear_engine_t *engine = (velawear_engine_t *)arg;
85	  velawear_state_t state;
86	  velawear_event_t event;
87	  int ret;
88	
89	  syslog(LOG_INFO, "[Decision] Thread started\n");
90	
91	  while (engine->running)
92	    {
93	      /* Sleep for decision interval */
94	
95	      usleep(100000);  /* 100ms */
96	
97	      /* Get current state */
98	
99	      /* TODO: Get state from state manager */
100	
101	      /* Evaluate rules by priority */
102	
103	      pthread_mutex_lock(&engine->lock);
104	
105	      for (int i = 0; i < engine->rule_count; i++)
106	        {
107	          if (!engine->rules[i].enabled)
108	            {
109	              continue;
110	            }
111	
112	          if (engine->rules[i].condition &&
113	              engine->rules[i].condition(&state, &event))
114	            {
115	              ret = engine->rules[i].action(&state,
116	                                            engine->rules[i].context);
117	              if (ret < 0)
118	                {
119	                  syslog(LOG_WARNING,
120	                         "[Decision] Rule '%s' action failed: %d\n",
121	                         engine->rules[i].name, ret);
122	                }
123	
124	              /* For emergency rules, stop after first match */
125	
126	              if (engine->rules[i].layer == 0)
127	                {
128	                  break;
129	                }
130	            }
131	        }
132	
133	      pthread_mutex_unlock(&engine->lock);
134	    }
135	
136	  syslog(LOG_INFO, "[Decision] Thread stopped\n");
137	  return NULL;
138	}
139	
140	/****************************************************************************
141	 * Public Functions
142	 ****************************************************************************/
143	
144	int decision_engine_init(velawear_engine_t *engine, velawear_config_t *config)
145	{
146	  memset(engine, 0, sizeof(velawear_engine_t));
147	
148	  pthread_mutex_init(&engine->lock, NULL);
149	  engine->config = config;
150	  engine->running = false;
151	
152	  /* Register hardcoded emergency rules */
153	
154	  decision_engine_add_rule(engine, "fall_detected", 0,
155	                           VELAWEAR_PRIORITY_CRITICAL,
156	                           fall_detected_condition,
157	                           fall_detected_action, NULL);
158	
159	  decision_engine_add_rule(engine, "heart_rate_critical", 0,
160	                           VELAWEAR_PRIORITY_CRITICAL,
161	                           heart_rate_critical_condition,
162	                           heart_rate_critical_action, NULL);
163	
164	  decision_engine_add_rule(engine, "battery_critical", 0,
165	                           VELAWEAR_PRIORITY_HIGH,
166	                           battery_critical_condition,
167	                           battery_critical_action, NULL);
168	
169	  syslog(LOG_INFO, "[Decision] Initialized with %d rules\n",
170	         engine->rule_count);
171	  return VELAWEAR_OK;
172	}
173	
174	int decision_engine_start(velawear_engine_t *engine)
175	{
176	  int ret;
177	
178	  if (engine->running)
179	    {
180	      return VELAWEAR_ERR_BUSY;
181	    }
182	
183	  engine->running = true;
184	
185	  ret = pthread_create(&engine->thread, NULL, decision_engine_thread, engine);
186	  if (ret != 0)
187	    {
188	      syslog(LOG_ERR, "[Decision] Failed to create thread: %d\n", ret);
189	      engine->running = false;
190	      return VELAWEAR_ERR_IO;
191	    }
192	
193	  syslog(LOG_INFO, "[Decision] Started\n");
194	  return VELAWEAR_OK;
195	}
196	
197	void decision_engine_cleanup(velawear_engine_t *engine)
198	{
199	  if (engine->running)
200	    {
201	      engine->running = false;
202	      pthread_join(engine->thread, NULL);
203	    }
204	
205	  pthread_mutex_destroy(&engine->lock);
206	
207	  syslog(LOG_INFO, "[Decision] Cleaned up\n");
208	}
209	
210	int decision_engine_add_rule(velawear_engine_t *engine,
211	                             const char *name,
212	                             int layer,
213	                             uint32_t priority,
214	                             rule_condition_t condition,
215	                             rule_action_t action,
216	                             void *context)
217	{
218	  pthread_mutex_lock(&engine->lock);
219	
220	  if (engine->rule_count >= DECISION_RULES_MAX)
221	    {
222	      pthread_mutex_unlock(&engine->lock);
223	      return VELAWEAR_ERR_NOMEM;
224	    }
225	
226	  decision_rule_t *rule = &engine->rules[engine->rule_count];
227	  rule->id = engine->rule_count;
228	  strncpy(rule->name, name, sizeof(rule->name) - 1);
229	  rule->layer = layer;
230	  rule->priority = priority;
231	  rule->condition = condition;
232	  rule->action = action;
233	  rule->context = context;
234	  rule->enabled = true;
235	
236	  engine->rule_count++;
237	
238	  pthread_mutex_unlock(&engine->lock);
239	
240	  syslog(LOG_INFO, "[Decision] Added rule '%s' (layer=%d, priority=%d)\n",
241	         name, layer, priority);
242	  return rule->id;
243	}
244	
245	int decision_engine_remove_rule(velawear_engine_t *engine, int rule_id)
246	{
247	  pthread_mutex_lock(&engine->lock);
248	
249	  if (rule_id < 0 || rule_id >= engine->rule_count)
250	    {
251	      pthread_mutex_unlock(&engine->lock);
252	      return VELAWEAR_ERR_INVAL;
253	    }
254	
255	  engine->rules[rule_id].enabled = false;
256	
257	  pthread_mutex_unlock(&engine->lock);
258	
259	  syslog(LOG_INFO, "[Decision] Disabled rule %d\n", rule_id);
260	  return VELAWEAR_OK;
261	}
262	
263	int decision_engine_evaluate(velawear_engine_t *engine,
264	                             velawear_state_t *state,
265	                             velawear_event_t *event)
266	{
267	  int ret;
268	
269	  pthread_mutex_lock(&engine->lock);
270	
271	  for (int i = 0; i < engine->rule_count; i++)
272	    {
273	      if (!engine->rules[i].enabled)
274	        {
275	          continue;
276	        }
277	
278	      if (engine->rules[i].condition &&
279	          engine->rules[i].condition(state, event))
280	        {
281	          ret = engine->rules[i].action(state, engine->rules[i].context);
282	          if (ret < 0)
283	            {
284	              syslog(LOG_WARNING,
285	                     "[Decision] Rule '%s' action failed: %d\n",
286	                     engine->rules[i].name, ret);
287	            }
288	
289	          /* For emergency rules, stop after first match */
290	
291	          if (engine->rules[i].layer == 0)
292	            {
293	              pthread_mutex_unlock(&engine->lock);
294	              return engine->rules[i].id;
295	            }
296	        }
297	    }
298	
299	  pthread_mutex_unlock(&engine->lock);
300	
301	  return -1;  /* No rule matched */
302	}
