1	/*
2	 * VelaWear Agent - IMU Sensor Driver Implementation
3	 *
4	 * Reads LSM6DSL IMU data for motion detection.
5	 *
6	 * Author: pjjuihj
7	 * Team: 329 - dela
8	 */
9	
10	#include <nuttx/config.h>
11	#include <stdio.h>
12	#include <stdlib.h>
13	#include <string.h>
14	#include <fcntl.h>
15	#include <unistd.h>
16	#include <errno.h>
17	#include <syslog.h>
18	#include <sys/ioctl.h>
19	#include <math.h>
20	
21	#include "velawear.h"
22	#include "imu_sensor.h"
23	
24	/****************************************************************************
25	 * Pre-processor Definitions
26	 ****************************************************************************/
27	
28	#define IMU_DEVICE_PATH         "/dev/imu0"
29	
30	/* Default thresholds (in m/s^2) */
31	
32	#define DEFAULT_MOVE_THRESHOLD  0.5f
33	#define DEFAULT_RUN_THRESHOLD   2.0f
34	#define DEFAULT_FALL_THRESHOLD  15.0f
35	
36	/****************************************************************************
37	 * Private Functions
38	 ****************************************************************************/
39	
40	static float calculate_magnitude(float x, float y, float z)
41	{
42	  return sqrtf(x * x + y * y + z * z);
43	}
44	
45	static void update_motion_state(imu_sensor_t *imu, imu_data_t *data)
46	{
47	  float accel_mag = calculate_magnitude(data->accel_x,
48	                                        data->accel_y,
49	                                        data->accel_z);
50	  float gyro_mag = calculate_magnitude(data->gyro_x,
51	                                       data->gyro_y,
52	                                       data->gyro_z);
53	
54	  /* Check for fall detection (sudden high acceleration) */
55	
56	  if (accel_mag > imu->threshold_fall)
57	    {
58	      imu->motion.fall_detected = true;
59	      syslog(LOG_WARNING, "[IMU] Fall detected! Accel: %.2f\n", accel_mag);
60	    }
61	
62	  /* Check for running (high acceleration + gyro) */
63	
64	  if (accel_mag > imu->threshold_run && gyro_mag > 1.0f)
65	    {
66	      imu->motion.is_running = true;
67	      imu->motion.is_moving = true;
68	      imu->motion.last_motion_time = time(NULL);
69	      imu->motion.motion_count++;
70	    }
71	  /* Check for moving (moderate acceleration) */
72	
73	  else if (accel_mag > imu->threshold_move)
74	    {
75	      imu->motion.is_moving = true;
76	      imu->motion.is_running = false;
77	      imu->motion.last_motion_time = time(NULL);
78	      imu->motion.motion_count++;
79	    }
80	  else
81	    {
82	      /* No significant motion */
83	
84	      if (time(NULL) - imu->motion.last_motion_time > 5)
85	        {
86	          imu->motion.is_moving = false;
87	          imu->motion.is_running = false;
88	        }
89	    }
90	
91	  imu->motion.motion_intensity = accel_mag;
92	}
93	
94	/****************************************************************************
95	 * Public Functions
96	 ****************************************************************************/
97	
98	int imu_sensor_init(imu_sensor_t *imu)
99	{
100	  memset(imu, 0, sizeof(imu_sensor_t));
101	
102	  /* Open IMU device */
103	
104	  imu->fd = open(IMU_DEVICE_PATH, O_RDONLY);
105	  if (imu->fd < 0)
106	    {
107	      syslog(LOG_ERR, "[IMU] Failed to open %s: %d\n",
108	             IMU_DEVICE_PATH, errno);
109	      return VELAWEAR_ERR_IO;
110	    }
111	
112	  /* Set default thresholds */
113	
114	  imu->threshold_move = DEFAULT_MOVE_THRESHOLD;
115	  imu->threshold_run = DEFAULT_RUN_THRESHOLD;
116	  imu->threshold_fall = DEFAULT_FALL_THRESHOLD;
117	
118	  imu->initialized = true;
119	  imu->buffer_index = 0;
120	
121	  syslog(LOG_INFO, "[IMU] Initialized\n");
122	  return VELAWEAR_OK;
123	}
124	
125	void imu_sensor_cleanup(imu_sensor_t *imu)
126	{
127	  if (imu->fd >= 0)
128	    {
129	      close(imu->fd);
130	    }
131	
132	  imu->initialized = false;
133	  syslog(LOG_INFO, "[IMU] Cleaned up\n");
134	}
135	
136	int imu_sensor_read(imu_sensor_t *imu, imu_data_t *data)
137	{
138	  struct lsm6dsl_sensor_data raw;
139	  int ret;
140	
141	  if (!imu->initialized)
142	    {
143	      return VELAWEAR_ERR_IO;
144	    }
145	
146	  ret = read(imu->fd, &raw, sizeof(raw));
147	  if (ret < 0)
148	    {
149	      syslog(LOG_ERR, "[IMU] Read failed: %d\n", errno);
150	      return VELAWEAR_ERR_IO;
151	    }
152	
153	  /* Convert raw data to float */
154	
155	  data->accel_x = raw.accel_x / 1000.0f;
156	  data->accel_y = raw.accel_y / 1000.0f;
157	  data->accel_z = raw.accel_z / 1000.0f;
158	  data->gyro_x = raw.gyro_x / 1000.0f;
159	  data->gyro_y = raw.gyro_y / 1000.0f;
160	  data->gyro_z = raw.gyro_z / 1000.0f;
161	  data->timestamp = time(NULL);
162	
163	  /* Store in buffer */
164	
165	  imu->buffer[imu->buffer_index] = *data;
166	  imu->buffer_index = (imu->buffer_index + 1) % IMU_BUFFER_SIZE;
167	
168	  /* Update motion state */
169	
170	  update_motion_state(imu, data);
171	
172	  return VELAWEAR_OK;
173	}
174	
175	int imu_sensor_read_buffer(imu_sensor_t *imu, imu_data_t *buffer,
176	                           int max_count)
177	{
178	  int count = 0;
179	
180	  for (int i = 0; i < max_count; i++)
181	    {
182	      if (imu_sensor_read(imu, &buffer[count]) < 0)
183	        {
184	          break;
185	        }
186	
187	      count++;
188	    }
189	
190	  return count;
191	}
192	
193	motion_state_t imu_sensor_get_motion_state(imu_sensor_t *imu)
194	{
195	  return imu->motion;
