#define VELAWEAR_PRIORITY_HIGH      2
#define VELAWEAR_PRIORITY_CRITICAL  3

/****************************************************************************
 * Type Definitions
 ****************************************************************************/

/* Event structure */

typedef struct velawear_event
{
  uint32_t type;
  uint32_t priority;
  uint32_t timestamp;
  union
    {
      struct
        {
          float x;
          float y;
          float z;
