#define VELAWEAR_EVENT_MOTION       2
#define VELAWEAR_EVENT_FALL         3
#define VELAWEAR_EVENT_AUDIO        4
#define VELAWEAR_EVENT_VOICE_CMD    5
#define VELAWEAR_EVENT_BLE_MSG      6
