  bool is_running;
  bool is_sleeping;
  float heart_rate;
  float temperature;

  /* Environment state */

  bool ble_connected;
  char ble_device_name[64];
  bool has_network;
  int signal_strength;

  /* History */

  uint32_t last_move_time;
  uint32_t last_interaction_time;
  uint32_t fall_count_today;
  uint32_t move_count_today;
} velawear_state_t;

/* Action structure */

typedef struct velawear_action
{
