37	int main(int argc, char *argv[])
38	{
39	  int ret;
40	
41	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
42	
43	  /* Initialize agent structure */
44	
45	  memset(&g_agent, 0, sizeof(velawear_agent_t));
46	  g_agent.running = false;
47	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
48	
49	  /* Set up signal handler */
50	
51	  signal(SIGTERM, velawear_signal_handler);
52	  signal(SIGINT, velawear_signal_handler);
53	
54	  /* Initialize subsystems */
55	
56	  ret = velawear_init(&g_agent);
57	  if (ret < 0)
58	    {
59	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
60	      return EXIT_FAILURE;
61	    }
62	
63	  /* Start the agent */
64	
65	  ret = velawear_start(&g_agent);
66	  if (ret < 0)
67	    {
68	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
69	      velawear_cleanup(&g_agent);
70	      return EXIT_FAILURE;
71	    }
72	
73	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
74	
75	  /* Main loop - wait for termination signal */
76	
77	  while (g_agent.running)
78	    {
79	      sleep(1);
80	    }
81	
82	  /* Cleanup */
83	
84	  velawear_cleanup(&g_agent);
85	  syslog(LOG_INFO, "[VelaWear] Agent stopped\n");
